"""
Module for virtual environment health checking and repair.

This module provides utilities to check the health of Python virtual environments
and repair common issues like broken symlinks, invalid paths, and missing interpreters.
"""

import json
import logging
import os
import re
import shutil
import subprocess
import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import Optional, Union

from .python import (
    PythonInfo,
    extract_version_from_pyvenv_cfg,
    find_python,
    get_or_install_python,
)

logger = logging.getLogger(__name__)


# Absolute path to a qBraid environment's ``pyenv`` directory as embedded in
# venv activation scripts. Anchors on the path itself (not the assignment
# syntax) so it matches every form emitted by python/uv venv activate scripts:
#   VIRTUAL_ENV="/.../pyenv"                     (quoted, POSIX)
#   VIRTUAL_ENV=/.../pyenv                       (unquoted, POSIX)
#   VIRTUAL_ENV=$(cygpath /.../pyenv)            (cygwin/msys)
#   set "VIRTUAL_ENV=C:\...\pyenv"               (Windows activate.bat / .ps1)
# Robustness matters here: modern (uv / Python 3.12) activate scripts write the
# unquoted form, so a quote-dependent regex silently fails to relocate the env,
# leaving a stale VIRTUAL_ENV path and making `qbraid envs activate` a no-op.
#
# The match is anchored to a leading assignment boundary (``(?<!...)``) so the
# path is captured from its start, not from the last ``/`` before ``.qbraid``.
# Without that anchor, a home dir containing a space (``/Users/John Doe/...``)
# would match only the tail and get corrupted on rewrite. Both ``/`` and ``\``
# separators (and an optional ``C:`` drive letter) are accepted so the Windows
# ``activate.bat`` / ``Activate.ps1`` forms are handled too. The prefix segment
# allows spaces since the leading edge is already boundary-anchored.
_ENV_PYENV_PATH_RE = re.compile(
    r"""(?<![^=\s('"])"""  # leading edge: an assignment boundary (or start), not mid-path
    r"""(?:[A-Za-z]:)?"""  # optional Windows drive letter
    r"""[\\/]"""  # leading path separator
    r"""(?:[^\r\n"'`)]*[\\/])?"""  # prefix dirs (may contain spaces; either separator)
    r"""\.qbraid[\\/]environments[\\/]"""  # the qBraid env marker
    r"""[^\s"'`)\\/]+[\\/]pyenv"""  # <slug>/pyenv
)


def rewrite_env_pyenv_paths(content: str, pyenv_path: Union[str, Path]) -> str:
    """Rewrite every embedded ``.qbraid/environments/*/pyenv`` path to ``pyenv_path``.

    Used to relocate activation scripts (and any file embedding the venv path)
    after an environment is downloaded, moved, or repaired. Matching is
    quote-agnostic; see :data:`_ENV_PYENV_PATH_RE`. A ``lambda`` replacement is
    used so backslashes in ``pyenv_path`` are never treated as regex group
    references. ``pyenv_path`` may be a str (e.g. a POSIX upload target that must
    keep forward slashes on all platforms) or a Path.
    """
    target = str(pyenv_path)
    return _ENV_PYENV_PATH_RE.sub(lambda _: target, content)


def find_stale_env_pyenv_paths(content: str, pyenv_path: Union[str, Path]) -> list[str]:
    """Return embedded pyenv paths that differ from ``pyenv_path``.

    A non-empty result means the content still references a build-time or
    otherwise stale environment location and needs relocation.
    """
    target = str(pyenv_path)
    return [p for p in _ENV_PYENV_PATH_RE.findall(content) if p != target]


@dataclass
class VenvHealthIssue:
    """A single issue found during venv health check.

    Attributes:
        category: Issue category (e.g., "symlink", "pyvenv.cfg", "kernel")
        severity: "error" (venv broken) or "warning" (venv may work)
        message: Human-readable description
        path: Path to affected file (if applicable)
        repairable: Whether this issue can be automatically repaired
    """

    category: str
    severity: str  # "error" or "warning"
    message: str
    path: Optional[Path] = None
    repairable: bool = True


@dataclass
class VenvHealthResult:
    """Result of venv health check.

    Attributes:
        is_healthy: True if no errors found (warnings ok)
        issues: List of issues found
        python_version: Detected Python version (if available)
        python_executable: Path to Python executable (if valid)
    """

    is_healthy: bool
    issues: list[VenvHealthIssue] = field(default_factory=list)
    python_version: Optional[str] = None
    python_executable: Optional[Path] = None

    @property
    def errors(self) -> list[VenvHealthIssue]:
        """Return only error-level issues."""
        return [i for i in self.issues if i.severity == "error"]

    @property
    def warnings(self) -> list[VenvHealthIssue]:
        """Return only warning-level issues."""
        return [i for i in self.issues if i.severity == "warning"]

    @property
    def repairable_issues(self) -> list[VenvHealthIssue]:
        """Return issues that can be automatically repaired."""
        return [i for i in self.issues if i.repairable]


def _check_pyvenv_cfg(pyenv_path: Path) -> list[VenvHealthIssue]:
    """Check pyvenv.cfg for issues.

    Args:
        pyenv_path: Path to pyenv directory (venv root)

    Returns:
        List of issues found
    """
    issues = []
    pyvenv_cfg = pyenv_path / "pyvenv.cfg"

    if not pyvenv_cfg.exists():
        issues.append(
            VenvHealthIssue(
                category="pyvenv.cfg",
                severity="error",
                message="pyvenv.cfg file is missing",
                path=pyvenv_cfg,
                repairable=True,
            )
        )
        return issues

    try:
        with open(pyvenv_cfg, "r", encoding="utf-8") as f:
            content = f.read()

        # Check for required fields
        if "home" not in content.lower():
            issues.append(
                VenvHealthIssue(
                    category="pyvenv.cfg",
                    severity="warning",
                    message="pyvenv.cfg missing 'home' field",
                    path=pyvenv_cfg,
                    repairable=True,
                )
            )

        # Check if home path exists
        for line in content.split("\n"):
            if line.lower().startswith("home"):
                parts = line.split("=", 1)
                if len(parts) == 2:
                    home_path = Path(parts[1].strip())
                    if not home_path.exists():
                        issues.append(
                            VenvHealthIssue(
                                category="pyvenv.cfg",
                                severity="error",
                                message=f"pyvenv.cfg 'home' path does not exist: {home_path}",
                                path=pyvenv_cfg,
                                repairable=True,
                            )
                        )

    except OSError as err:
        issues.append(
            VenvHealthIssue(
                category="pyvenv.cfg",
                severity="error",
                message=f"Cannot read pyvenv.cfg: {err}",
                path=pyvenv_cfg,
                repairable=False,
            )
        )

    return issues


def _check_python_symlinks(pyenv_path: Path) -> list[VenvHealthIssue]:
    """Check Python symlinks in bin directory.

    Args:
        pyenv_path: Path to pyenv directory (venv root)

    Returns:
        List of issues found
    """
    issues = []

    if sys.platform == "win32":
        bin_dir = pyenv_path / "Scripts"
        python_names = ["python.exe", "python3.exe"]
    else:
        bin_dir = pyenv_path / "bin"
        python_names = ["python", "python3"]

    if not bin_dir.exists():
        issues.append(
            VenvHealthIssue(
                category="structure",
                severity="error",
                message=f"bin directory is missing: {bin_dir}",
                path=bin_dir,
                repairable=False,  # Can't repair missing bin dir
            )
        )
        return issues

    found_valid_python = False

    for name in python_names:
        python_path = bin_dir / name

        if not python_path.exists() and not python_path.is_symlink():
            continue

        # Check if it's a broken symlink
        if python_path.is_symlink():
            try:
                target = python_path.resolve()
                if not target.exists():
                    issues.append(
                        VenvHealthIssue(
                            category="symlink",
                            severity="error",
                            message=f"Broken symlink: {python_path} -> {target}",
                            path=python_path,
                            repairable=True,
                        )
                    )
                    continue
            except OSError as err:
                issues.append(
                    VenvHealthIssue(
                        category="symlink",
                        severity="error",
                        message=f"Cannot resolve symlink {python_path}: {err}",
                        path=python_path,
                        repairable=True,
                    )
                )
                continue

        # Verify Python works
        try:
            result = subprocess.run(
                [str(python_path), "--version"],
                capture_output=True,
                timeout=10,
                check=False,
            )
            if result.returncode == 0:
                found_valid_python = True
            else:
                issues.append(
                    VenvHealthIssue(
                        category="python",
                        severity="error",
                        message=f"Python at {python_path} fails to run: {result.stderr.decode()}",
                        path=python_path,
                        repairable=True,
                    )
                )
        except (subprocess.TimeoutExpired, OSError) as err:
            issues.append(
                VenvHealthIssue(
                    category="python",
                    severity="error",
                    message=f"Cannot execute Python at {python_path}: {err}",
                    path=python_path,
                    repairable=True,
                )
            )

    if not found_valid_python:
        # Check if any python exists but all are broken
        python_exists = any(
            (bin_dir / name).exists() or (bin_dir / name).is_symlink() for name in python_names
        )
        if not python_exists:
            issues.append(
                VenvHealthIssue(
                    category="python",
                    severity="error",
                    message=f"No Python executable found in {bin_dir}",
                    path=bin_dir,
                    repairable=True,
                )
            )

    return issues


def _check_activate_script(pyenv_path: Path) -> list[VenvHealthIssue]:
    """Check activate script for path issues.

    Args:
        pyenv_path: Path to pyenv directory (venv root)

    Returns:
        List of issues found
    """
    issues = []

    # Inspect every variant _fix_activate_script can repair, so a stale path
    # living only in e.g. Activate.ps1 or activate.fish still surfaces as an
    # issue and gates `repair`. The first entry is the primary script; its
    # absence (not just a stale path) is itself a repairable warning.
    if sys.platform == "win32":
        activate_scripts = ["Scripts/activate.bat", "Scripts/Activate.ps1"]
    else:
        activate_scripts = ["bin/activate", "bin/activate.csh", "bin/activate.fish"]

    primary = pyenv_path / activate_scripts[0]
    if not primary.exists():
        issues.append(
            VenvHealthIssue(
                category="activate",
                severity="warning",
                message="Activate script is missing",
                path=primary,
                repairable=True,
            )
        )
        return issues

    for rel_path in activate_scripts:
        activate_path = pyenv_path / rel_path
        if not activate_path.exists():
            continue

        try:
            with open(activate_path, "r", encoding="utf-8") as f:
                content = f.read()

            # Check for stale embedded pyenv paths (quote-agnostic: handles
            # quoted, unquoted, and cygpath-wrapped VIRTUAL_ENV assignments
            # alike). A path may appear more than once (e.g. the cygpath and
            # plain branches); dedup so each distinct stale path is reported a
            # single time per file.
            stale_paths = dict.fromkeys(find_stale_env_pyenv_paths(content, pyenv_path))
            for stale in stale_paths:
                # A stale path to a non-existent directory makes activation a
                # silent no-op (PATH gets a bogus dir prepended, python/pip fall
                # through to system) -> treat as an error so `repair` will run.
                # A stale path that still exists is only a warning.
                severity = "warning" if Path(stale).exists() else "error"
                issues.append(
                    VenvHealthIssue(
                        category="activate",
                        severity=severity,
                        message=f"Activate script has stale VIRTUAL_ENV path: {stale}",
                        path=activate_path,
                        repairable=True,
                    )
                )

        except OSError as err:
            issues.append(
                VenvHealthIssue(
                    category="activate",
                    severity="warning",
                    message=f"Cannot read activate script: {err}",
                    path=activate_path,
                    repairable=False,
                )
            )

    return issues


def _check_kernel_json(env_path: Path) -> list[VenvHealthIssue]:
    """Check kernel.json for path issues.

    Args:
        env_path: Path to environment directory (contains kernels/)

    Returns:
        List of issues found
    """
    issues: list[VenvHealthIssue] = []
    kernels_dir = env_path / "kernels"

    if not kernels_dir.exists():
        return issues  # No kernels = no issues (kernel is optional)

    for kernel_dir in kernels_dir.iterdir():
        if not kernel_dir.is_dir():
            continue

        kernel_json = kernel_dir / "kernel.json"
        if not kernel_json.exists():
            continue

        try:
            with open(kernel_json, "r", encoding="utf-8") as f:
                data = json.load(f)

            # Check argv[0] (Python path)
            if "argv" in data and data["argv"]:
                python_path = Path(data["argv"][0])
                if not python_path.exists():
                    # Check if it's a symlink
                    if python_path.is_symlink():
                        try:
                            target = python_path.resolve()
                            issues.append(
                                VenvHealthIssue(
                                    category="kernel",
                                    severity="error",
                                    message=(
                                        f"kernel.json has broken Python path: "
                                        f"{python_path} -> {target}"
                                    ),
                                    path=kernel_json,
                                    repairable=True,
                                )
                            )
                        except OSError:
                            issues.append(
                                VenvHealthIssue(
                                    category="kernel",
                                    severity="error",
                                    message=f"kernel.json has invalid Python path: {python_path}",
                                    path=kernel_json,
                                    repairable=True,
                                )
                            )
                    else:
                        issues.append(
                            VenvHealthIssue(
                                category="kernel",
                                severity="error",
                                message=f"kernel.json Python path does not exist: {python_path}",
                                path=kernel_json,
                                repairable=True,
                            )
                        )

        except (json.JSONDecodeError, OSError) as err:
            issues.append(
                VenvHealthIssue(
                    category="kernel",
                    severity="warning",
                    message=f"Cannot read kernel.json at {kernel_json}: {err}",
                    path=kernel_json,
                    repairable=False,
                )
            )

    return issues


def is_venv_healthy(env_path: Path) -> VenvHealthResult:
    """Check the health of a virtual environment.

    Performs comprehensive checks:
    - pyvenv.cfg exists and has valid paths
    - Python symlinks are not broken
    - Python executable works
    - activate script has correct paths
    - kernel.json (if exists) has valid Python path

    Args:
        env_path: Path to environment directory.
                  For qBraid envs, this is the slug directory (containing pyenv/).
                  For standard venvs, this is the venv directory.

    Returns:
        VenvHealthResult with health status and any issues found
    """
    issues = []

    # Determine pyenv path
    # qBraid structure: env_path/pyenv/bin/python
    # Standard venv: env_path/bin/python
    pyenv_path = env_path / "pyenv"
    if not pyenv_path.exists():
        pyenv_path = env_path  # Assume standard venv structure

    # Check pyvenv.cfg
    issues.extend(_check_pyvenv_cfg(pyenv_path))

    # Check Python symlinks
    issues.extend(_check_python_symlinks(pyenv_path))

    # Check activate script
    issues.extend(_check_activate_script(pyenv_path))

    # Check kernel.json (in parent env_path, not pyenv_path)
    issues.extend(_check_kernel_json(env_path))

    # Determine overall health (errors = unhealthy, warnings = healthy)
    has_errors = any(i.severity == "error" for i in issues)

    # Try to get Python version and executable
    python_version = None
    python_executable = None

    pyvenv_cfg = pyenv_path / "pyvenv.cfg"
    python_version = extract_version_from_pyvenv_cfg(pyvenv_cfg)

    if sys.platform == "win32":
        python_path = pyenv_path / "Scripts" / "python.exe"
    else:
        python_path = pyenv_path / "bin" / "python"

    if python_path.exists() and not python_path.is_symlink():
        python_executable = python_path
    elif python_path.is_symlink():
        try:
            target = python_path.resolve()
            if target.exists():
                python_executable = python_path
        except OSError:
            pass

    # Check pip is importable (catches venvs still being set up)
    if python_executable:
        issues.extend(_check_pip_ready(python_executable))
        has_errors = any(i.severity == "error" for i in issues)

    return VenvHealthResult(
        is_healthy=not has_errors,
        issues=issues,
        python_version=python_version,
        python_executable=python_executable,
    )


def _check_pip_ready(python_path: Path) -> list:
    """Check if pip is importable in the venv's Python."""
    try:
        result = subprocess.run(
            [str(python_path), "-c", "import pip"],
            capture_output=True,
            timeout=10,
            check=False,
        )
        if result.returncode != 0:
            return [
                VenvHealthIssue(
                    category="pip",
                    message="pip is not available in this environment",
                    severity="warning",
                    repairable=True,
                )
            ]
    except (subprocess.TimeoutExpired, OSError):
        return [
            VenvHealthIssue(
                category="pip",
                message="Could not verify pip availability",
                severity="warning",
                repairable=False,
            )
        ]

    return []


def is_pip_ready(env_path: Path) -> bool:
    """Quick check if pip is importable in an environment.

    Useful for gating package installs after venv creation —
    the venv directory may exist but pip may not be ready yet.

    Args:
        env_path: Path to environment directory.

    Returns:
        True if pip is importable, False otherwise.
    """
    pyenv_path = env_path / "pyenv"
    if not pyenv_path.exists():
        pyenv_path = env_path

    python_path = pyenv_path / "bin" / "python"
    if not python_path.exists():
        python_path = pyenv_path / "Scripts" / "python.exe"

    if not python_path.exists():
        return False

    try:
        result = subprocess.run(
            [str(python_path), "-c", "import pip"],
            capture_output=True,
            timeout=10,
            check=False,
        )
        return result.returncode == 0
    except (subprocess.TimeoutExpired, OSError):
        return False


def _fix_python_symlinks(
    pyenv_path: Path,
    python_info: PythonInfo,
) -> list[str]:
    """Fix Python symlinks in venv.

    Args:
        pyenv_path: Path to pyenv directory
        python_info: Python interpreter to link to

    Returns:
        List of actions taken
    """
    actions = []

    if sys.platform == "win32":
        bin_dir = pyenv_path / "Scripts"
        # On Windows, copy executables instead of symlinks
        python_names = ["python.exe", "python3.exe", "pythonw.exe"]
    else:
        bin_dir = pyenv_path / "bin"
        python_names = ["python", "python3"]

        # Also add version-specific links
        version_parts = python_info.version.split(".")
        if len(version_parts) >= 2:
            python_names.append(f"python{version_parts[0]}.{version_parts[1]}")

    for name in python_names:
        link_path = bin_dir / name

        # Remove existing broken link or file
        if link_path.exists() or link_path.is_symlink():
            try:
                link_path.unlink()
                actions.append(f"Removed broken {name}")
            except OSError as err:
                logger.warning("Failed to remove %s: %s", link_path, err)
                continue

        # Create new symlink
        try:
            if sys.platform == "win32":
                # On Windows, copy the executable
                shutil.copy2(python_info.path, link_path)
                actions.append(f"Copied Python to {name}")
            else:
                link_path.symlink_to(python_info.path)
                actions.append(f"Created symlink {name} -> {python_info.path}")
        except OSError as err:
            logger.warning("Failed to create symlink %s: %s", link_path, err)

    return actions


def _fix_pyvenv_cfg(
    pyenv_path: Path,
    python_info: PythonInfo,
) -> list[str]:
    """Fix pyvenv.cfg with correct paths.

    Args:
        pyenv_path: Path to pyenv directory
        python_info: Python interpreter info

    Returns:
        List of actions taken
    """
    actions = []
    pyvenv_cfg = pyenv_path / "pyvenv.cfg"

    # Determine Python home directory
    python_home = python_info.path.parent
    if python_home.name in ("bin", "Scripts"):
        python_home = python_home.parent

    # Read existing content or create new
    existing_content = {}
    if pyvenv_cfg.exists():
        try:
            with open(pyvenv_cfg, "r", encoding="utf-8") as f:
                for line in f:
                    if "=" in line:
                        key, value = line.split("=", 1)
                        existing_content[key.strip()] = value.strip()
        except OSError:
            pass

    # Update fields
    existing_content["home"] = str(python_home)
    existing_content["version"] = python_info.version

    # Preserve include-system-site-packages if set, otherwise default to false
    if "include-system-site-packages" not in existing_content:
        existing_content["include-system-site-packages"] = "false"

    # Write updated config
    try:
        with open(pyvenv_cfg, "w", encoding="utf-8") as f:
            for key, value in existing_content.items():
                f.write(f"{key} = {value}\n")
        actions.append(f"Updated pyvenv.cfg with home={python_home}")
    except OSError as err:
        logger.warning("Failed to update pyvenv.cfg: %s", err)

    return actions


def _fix_activate_script(pyenv_path: Path) -> list[str]:
    """Fix embedded venv paths in the activation scripts.

    Rewrites any stale ``.qbraid/environments/*/pyenv`` path (e.g. the build-time
    slug location left behind after a download) to ``pyenv_path``. Covers every
    POSIX activate variant, and the Windows ``activate.bat``.

    Args:
        pyenv_path: Path to pyenv directory

    Returns:
        List of actions taken
    """
    actions: list[str] = []

    if sys.platform == "win32":
        activate_scripts = ["Scripts/activate.bat", "Scripts/Activate.ps1"]
    else:
        activate_scripts = ["bin/activate", "bin/activate.csh", "bin/activate.fish"]

    for rel_path in activate_scripts:
        activate_path = pyenv_path / rel_path
        if not activate_path.exists():
            continue

        try:
            with open(activate_path, "r", encoding="utf-8") as f:
                content = f.read()

            new_content = rewrite_env_pyenv_paths(content, pyenv_path)

            if new_content != content:
                with open(activate_path, "w", encoding="utf-8") as f:
                    f.write(new_content)
                actions.append(f"Updated {activate_path.name} VIRTUAL_ENV to {pyenv_path}")

        except OSError as err:
            logger.warning("Failed to fix activate script %s: %s", activate_path, err)

    return actions


def _fix_kernel_json(env_path: Path, pyenv_path: Path) -> list[str]:
    """Fix kernel.json Python path.

    Args:
        env_path: Path to environment directory (contains kernels/)
        pyenv_path: Path to pyenv directory

    Returns:
        List of actions taken
    """
    actions: list[str] = []
    kernels_dir = env_path / "kernels"

    if not kernels_dir.exists():
        return actions

    if sys.platform == "win32":
        python_path = pyenv_path / "Scripts" / "python.exe"
    else:
        python_path = pyenv_path / "bin" / "python"

    for kernel_dir in kernels_dir.iterdir():
        if not kernel_dir.is_dir():
            continue

        kernel_json = kernel_dir / "kernel.json"
        if not kernel_json.exists():
            continue

        try:
            with open(kernel_json, "r", encoding="utf-8") as f:
                data = json.load(f)

            if "argv" in data and data["argv"]:
                old_path = data["argv"][0]
                if old_path != str(python_path):
                    data["argv"][0] = str(python_path)
                    with open(kernel_json, "w", encoding="utf-8") as f:
                        json.dump(data, f, indent=1)
                    actions.append(f"Updated kernel.json python path: {old_path} -> {python_path}")

        except (json.JSONDecodeError, OSError) as err:
            logger.warning("Failed to fix kernel.json at %s: %s", kernel_json, err)

    return actions


def _fix_shebang_scripts(pyenv_path: Path) -> list[str]:
    """Fix shebangs in executable scripts.

    Args:
        pyenv_path: Path to pyenv directory

    Returns:
        List of actions taken
    """
    actions: list[str] = []

    if sys.platform == "win32":
        return actions  # Windows doesn't use shebangs

    bin_dir = pyenv_path / "bin"
    if not bin_dir.exists():
        return actions

    # Get the correct Python path
    python_path = bin_dir / "python"
    if not python_path.exists():
        python_path = bin_dir / "python3"
    if not python_path.exists():
        return actions

    new_shebang = f"#!{python_path}"

    for exe_file in bin_dir.iterdir():
        if not exe_file.is_file():
            continue
        if exe_file.name in ("python", "python3") or exe_file.name.startswith("python3."):
            continue

        # Check if executable
        try:
            if not os.access(exe_file, os.X_OK):
                continue
        except OSError:
            continue

        try:
            with open(exe_file, "rb") as f:
                first_line = f.readline()
                if not first_line.startswith(b"#!"):
                    continue
                rest = f.read()

            # Check if shebang points to a non-existent Python
            shebang = first_line.decode("utf-8", errors="ignore").strip()
            if "python" in shebang.lower():
                old_python = shebang[2:].strip()  # Remove #!
                if not Path(old_python).exists():
                    # Replace shebang
                    new_content = (new_shebang + "\n").encode("utf-8") + rest
                    with open(exe_file, "wb") as f:
                        f.write(new_content)
                    actions.append(f"Fixed shebang in {exe_file.name}")

        except (OSError, UnicodeDecodeError) as err:
            logger.debug("Failed to check/fix shebang in %s: %s", exe_file, err)

    return actions


def repair_venv(
    env_path: Path,
    python_version: Optional[str] = None,
    auto_install_python: bool = True,
) -> tuple[bool, list[str]]:
    """Repair a broken virtual environment.

    This function attempts to fix common venv issues:
    1. Detects required Python version from pyvenv.cfg
    2. Finds or installs matching Python (via uv if available)
    3. Updates symlinks in bin/ directory
    4. Updates pyvenv.cfg with correct paths
    5. Updates kernel.json if present
    6. Updates activate script VIRTUAL_ENV

    Args:
        env_path: Path to environment directory
        python_version: Python version to use (e.g., "3.11"). If None, auto-detect.
        auto_install_python: If True and uv available, install Python if not found

    Returns:
        tuple[bool, list[str]]: (success, list of actions taken)

    Raises:
        RuntimeError: If Python cannot be found or installed
    """
    actions = []

    # Determine pyenv path
    pyenv_path = env_path / "pyenv"
    if not pyenv_path.exists():
        pyenv_path = env_path

    # Step 1: Determine Python version
    if python_version is None:
        pyvenv_cfg = pyenv_path / "pyvenv.cfg"
        python_version = extract_version_from_pyvenv_cfg(pyvenv_cfg)

    if python_version is None:
        # Default to current Python's version
        python_version = f"{sys.version_info.major}.{sys.version_info.minor}"
        actions.append(f"No Python version detected, using current: {python_version}")

    # Step 2: Find or install matching Python
    python_path = get_or_install_python(python_version, auto_install=auto_install_python)

    if python_path is None:
        raise RuntimeError(
            f"Cannot repair venv: Python {python_version} not found. "
            "Install Python manually, install uv, or provide a path to an existing interpreter."
        )

    # Get full Python info
    python_info = find_python(python_version)
    if python_info is None:
        # Create minimal PythonInfo
        python_info = PythonInfo(
            path=python_path,
            version=python_version,
            source="unknown",
        )

    actions.append(f"Using Python {python_info.version} at {python_info.path}")

    # Step 3: Fix symlinks
    symlink_actions = _fix_python_symlinks(pyenv_path, python_info)
    actions.extend(symlink_actions)

    # Step 4: Fix pyvenv.cfg
    cfg_actions = _fix_pyvenv_cfg(pyenv_path, python_info)
    actions.extend(cfg_actions)

    # Step 5: Fix activate script
    activate_actions = _fix_activate_script(pyenv_path)
    actions.extend(activate_actions)

    # Step 6: Fix kernel.json
    kernel_actions = _fix_kernel_json(env_path, pyenv_path)
    actions.extend(kernel_actions)

    # Step 7: Fix shebangs in other scripts
    shebang_actions = _fix_shebang_scripts(pyenv_path)
    actions.extend(shebang_actions)

    # Verify repair was successful
    health = is_venv_healthy(env_path)
    success = health.is_healthy

    if not success:
        remaining_errors = [i.message for i in health.errors]
        actions.append(f"Repair incomplete, remaining issues: {remaining_errors}")

    return success, actions


def relocate_venv(
    env_path: Path,
    new_path: Path,
    update_registry: bool = True,
) -> tuple[bool, list[str]]:
    """Move a virtual environment to a new location.

    This function:
    1. Moves the directory
    2. Updates all internal paths (pyvenv.cfg, activate, kernel.json, shebangs)
    3. Optionally updates the environment registry

    Args:
        env_path: Current path to environment
        new_path: New path for environment
        update_registry: If True, update the environment registry

    Returns:
        tuple[bool, list[str]]: (success, list of actions taken)

    Raises:
        FileExistsError: If new_path already exists
        OSError: If move operation fails
    """
    actions = []

    if new_path.exists():
        raise FileExistsError(f"Target path already exists: {new_path}")

    # Move the directory
    shutil.move(str(env_path), str(new_path))
    actions.append(f"Moved environment from {env_path} to {new_path}")

    # Determine pyenv path
    pyenv_path = new_path / "pyenv"
    if not pyenv_path.exists():
        pyenv_path = new_path

    # Fix activate script (most important for relocation)
    activate_actions = _fix_activate_script(pyenv_path)
    actions.extend(activate_actions)

    # Fix shebangs
    shebang_actions = _fix_shebang_scripts(pyenv_path)
    actions.extend(shebang_actions)

    # Fix kernel.json
    kernel_actions = _fix_kernel_json(new_path, pyenv_path)
    actions.extend(kernel_actions)

    # Update registry if requested
    if update_registry:
        try:
            # Import here to avoid circular dependency
            from .registry import (  # pylint: disable=import-outside-toplevel
                EnvironmentRegistryManager,
            )

            registry = EnvironmentRegistryManager()

            # Find environment by old path
            for env_id, entry in registry.list_environments().items():
                if entry.path == env_path:
                    registry.update_environment(env_id, path=new_path)
                    actions.append(f"Updated registry path for env_id {env_id}")
                    break

        except Exception as err:  # pylint: disable=broad-exception-caught
            logger.warning("Failed to update registry: %s", err)
            actions.append(f"Warning: Failed to update registry: {err}")

    # Verify health after relocation
    health = is_venv_healthy(new_path)
    success = health.is_healthy

    return success, actions


